'use client';

import { useEffect, useId } from 'react';

import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { Wash } from '@/registry/ndeko/ui/wash';

import { SECTION } from './data';
import { EmailForm } from './email-form';
import { QueueCard } from './queue-card';
import {
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  resolvedCountOf,
  SCRIPT,
  SEND_MS,
  type CtaState,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

function spokenLineOf(state: CtaState) {
  if (state.form === 'invalid') {
    return 'Enter an address like name@company.com';
  }
  if (state.form === 'sending') {
    return 'Sending your sign-in link';
  }
  if (state.form === 'sent') {
    return `We sent a sign-in link to ${state.sentTo}`;
  }
  return '';
}

export default function Ctas03() {
  const { ref, isAutoplaying, state, act, pressed, isFinished, restart } =
    useSession(SESSION);
  const titleId = useId();
  const isSending = state.form === 'sending';
  const resolved = resolvedCountOf(state);
  const message = spokenUnless(isAutoplaying, spokenLineOf(state));
  const canReplay = isFinished && !isAutoplaying;

  useKeptHeight(ref);

  useEffect(() => {
    if (!isSending) {
      return;
    }
    const timer = setTimeout(() => act({ type: 'sent' }), SEND_MS);
    return () => clearTimeout(timer);
  }, [isSending, act]);

  return (
    <div ref={ref} className='@container min-h-[33rem]'>
      <section
        aria-labelledby={titleId}
        className='px-4 py-12 @2xl:px-6 @2xl:py-16 @5xl:px-8'
      >
        <div className='surface-brand relative isolate mx-auto grid max-w-6xl grid-cols-1 gap-8 rounded-2xl p-6 @2xl:p-10 @3xl:grid-cols-[minmax(0,1fr)_minmax(0,22rem)] @3xl:items-center @3xl:gap-12'>
          <Wash />
          <div className='flex flex-col gap-6'>
            <div className='flex max-w-xl flex-col gap-2'>
              <h2
                id={titleId}
                className='text-2xl font-semibold text-balance @2xl:text-3xl'
              >
                {SECTION.title}
              </h2>
              <p className='text-muted-foreground text-base text-pretty'>
                {SECTION.description}
              </p>
            </div>
            <EmailForm
              email={state.email}
              form={state.form}
              attempts={state.attempts}
              sentTo={state.sentTo}
              isPressed={pressed === 'submit'}
              onType={(value) => act({ type: 'typed', value })}
              onSubmit={() => act({ type: 'submitted' })}
              onReset={() => act({ type: 'reset' })}
            />
            <div className='flex'>
              <ReplayButton
                isShown={canReplay}
                onReplay={restart}
                label='Replay'
              />
            </div>
          </div>
          <QueueCard tasks={state.tasks} resolved={resolved} />
        </div>
      </section>
      <LiveRegion message={message} />
    </div>
  );
}

'use client';

import { useAnimate } from 'motion/react';
import { useEffect, useId } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import { ArrowRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold } from '@/registry/ndeko/ui/chat-motion';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';
import { Input } from '@/registry/ndeko/ui/input';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';

import { SECTION } from './data';
import type { FormStatus } from './session';

const LABELS: Record<MorphState, string> = {
  idle: 'Get started',
  busy: 'Sending',
  done: 'Sent',
};

const NUDGE = { x: [0, -4, 4, -2, 0] };

const NUDGE_TRANSITION = { duration: 0.3 };

function morphStateOf(form: FormStatus): MorphState {
  if (form === 'sending') {
    return 'busy';
  }
  if (form === 'sent') {
    return 'done';
  }
  return 'idle';
}

function describedByOf(isInvalid: boolean, hintId: string) {
  if (isInvalid) {
    return hintId;
  }
  return undefined;
}

type EmailFormProps = {
  email: string;
  form: FormStatus;
  attempts: number;
  sentTo: string;
  isPressed: boolean;
  onType: (value: string) => void;
  onSubmit: () => void;
  onReset: () => void;
};

export function EmailForm({
  email,
  form,
  attempts,
  sentTo,
  isPressed,
  onType,
  onSubmit,
  onReset,
}: EmailFormProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const [fieldRef, animate] = useAnimate<HTMLDivElement>();
  const hintId = useId();
  const inputId = useId();
  const isInvalid = form === 'invalid';
  const isSent = form === 'sent';
  const isLocked = form === 'sending' || isSent;
  const describedBy = describedByOf(isInvalid, hintId);
  const morphState = morphStateOf(form);

  useEffect(() => {
    const isRefusal = attempts > 0;
    if (!isRefusal || shouldReduceMotion) {
      return;
    }
    animate(fieldRef.current, NUDGE, NUDGE_TRANSITION);
  }, [attempts, shouldReduceMotion, animate, fieldRef]);

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onSubmit();
  }

  return (
    <form
      noValidate
      onSubmit={handleSubmit}
      className='@container flex flex-col gap-2'
    >
      <div className='flex flex-col gap-2 @md:flex-row'>
        <div ref={fieldRef} className='min-w-0 flex-1'>
          <label htmlFor={inputId} className='sr-only'>
            {SECTION.emailLabel}
          </label>
          <Input
            id={inputId}
            name='email'
            type='email'
            size='lg'
            autoComplete='email'
            placeholder={SECTION.placeholder}
            value={email}
            readOnly={isLocked}
            aria-invalid={isInvalid}
            aria-describedby={describedBy}
            onChange={(event) => onType(event.target.value)}
          />
        </div>
        <MorphButton
          type='submit'
          size='lg'
          state={morphState}
          labels={LABELS}
          idleIcon={<ArrowRightIcon />}
          className={cn('shrink-0', pressedSolidOf(isPressed))}
        />
      </div>
      <Fold open={isInvalid}>
        <p id={hintId} className='text-destructive-ink text-xs'>
          Enter an address like name@company.com
        </p>
      </Fold>
      <Fold open={isSent}>
        <div className='flex items-center gap-2 pt-1 text-[13px]'>
          {isSent && <DrawnCheck tone='success' entrance='draw' />}
          <span className='text-muted-foreground min-w-0 flex-1 truncate'>
            We sent a sign-in link to {sentTo}
          </span>
          <Button
            type='button'
            variant='ghost'
            size='sm'
            onClick={onReset}
            className='shrink-0'
          >
            Use another email
          </Button>
        </div>
      </Fold>
    </form>
  );
}

'use client';

import { MotionNumber } from '@/components/core/motion-number';
import { WordRoll } from '@/components/core/word-roll';
import { LoaderIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';

import { QUEUE, TASKS, type QueueTask } from './data';
import type { TaskStatus } from './session';

const STATUS_WORD: Record<TaskStatus, string> = {
  open: 'Open',
  replying: 'Replying',
  done: 'Done',
};

const STATUS_WORDS = Object.values(STATUS_WORD);

const STATUS_RANK: Record<TaskStatus, number> = {
  open: 0,
  replying: 1,
  done: 2,
};

function StatusGlyph({ status }: { status: TaskStatus }) {
  if (status === 'done') {
    return <DrawnCheck tone='success' entrance='draw' />;
  }
  if (status === 'replying') {
    return <LoaderIcon className='text-muted-foreground size-4 animate-spin' />;
  }
  return (
    <span className='hairline-ring ring-foreground/25 size-3.5 rounded-full' />
  );
}

function dimmedOf(status: TaskStatus) {
  if (status === 'done') {
    return 'opacity-60';
  }
  return undefined;
}

type QueueRowProps = {
  task: QueueTask;
  status: TaskStatus;
};

function QueueRow({ task, status }: QueueRowProps) {
  const word = STATUS_WORD[status];

  return (
    <li
      className={cn(
        'bg-card dark:bg-foreground/[0.06] flex h-11 items-center gap-3 rounded-lg px-3 shadow-[0_1px_2px_rgb(0_0_0/0.04)] transition-opacity duration-300 ease-(--ease-out-strong)',
        dimmedOf(status)
      )}
    >
      <span className='flex size-[18px] shrink-0 items-center justify-center'>
        <Swap swapKey={status}>
          <StatusGlyph status={status} />
        </Swap>
      </span>
      <span className='min-w-0 flex-1 truncate text-[13px]'>
        <span className='sr-only'>{word}: </span>
        {task.title}
      </span>
      <span
        aria-hidden='true'
        className='text-muted-foreground w-14 shrink-0 text-end text-xs'
      >
        <WordRoll
          text={word}
          labels={STATUS_WORDS}
          value={STATUS_RANK[status]}
        />
      </span>
    </li>
  );
}

type QueueCardProps = {
  tasks: TaskStatus[];
  resolved: number;
};

export function QueueCard({ tasks, resolved }: QueueCardProps) {
  return (
    <div className='bg-foreground/[0.04] flex flex-col gap-3 rounded-xl p-3'>
      <div className='flex items-center justify-between gap-3 px-1'>
        <div className='flex min-w-0 items-center gap-2'>
          <h3 className='text-sm font-medium'>{QUEUE.title}</h3>
          <Badge variant='secondary'>{QUEUE.badge}</Badge>
        </div>
        <p className='text-muted-foreground flex shrink-0 items-baseline gap-1 text-xs tabular-nums'>
          <MotionNumber value={resolved} />
          <span>of {TASKS.length} done</span>
        </p>
      </div>
      <ul aria-label='Conversations waiting' className='flex flex-col gap-1.5'>
        {TASKS.map((task, index) => (
          <QueueRow key={task.id} task={task} status={tasks[index]} />
        ))}
      </ul>
    </div>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';

import { TASKS } from './data';

export type TaskStatus = 'open' | 'replying' | 'done';

export type FormStatus = 'idle' | 'invalid' | 'sending' | 'sent';

export type CtaState = {
  email: string;
  form: FormStatus;
  /** Counts the refused submits, so a second refusal nudges the field again. */
  attempts: number;
  sentTo: string;
  tasks: TaskStatus[];
};

export type CtaAction =
  | { type: 'typed'; value: string }
  | { type: 'submitted' }
  | { type: 'sent' }
  | { type: 'reset' }
  | { type: 'replying'; index: number }
  | { type: 'resolved'; index: number };

type Step = SessionStep<CtaState, CtaAction>;

const EMAIL_SHAPE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function isEmailLike(email: string) {
  return EMAIL_SHAPE.test(email.trim());
}

function allTasks(status: TaskStatus): TaskStatus[] {
  return TASKS.map(() => status);
}

export const INITIAL: CtaState = {
  email: '',
  form: 'idle',
  attempts: 0,
  sentTo: '',
  tasks: allTasks('open'),
};

function submitted(state: CtaState): CtaState {
  const isIdle = state.form === 'idle';
  const isRefused = state.form === 'invalid';
  const canSubmit = isIdle || isRefused;
  if (!canSubmit) {
    return state;
  }
  if (!isEmailLike(state.email)) {
    return { ...state, form: 'invalid', attempts: state.attempts + 1 };
  }
  return { ...state, form: 'sending' };
}

function sent(state: CtaState): CtaState {
  if (state.form !== 'sending') {
    return state;
  }
  return { ...state, form: 'sent', sentTo: state.email.trim() };
}

function withTask(
  state: CtaState,
  index: number,
  status: TaskStatus
): CtaState {
  const tasks = state.tasks.map((current, position) => {
    if (position === index) {
      return status;
    }
    return current;
  });
  return { ...state, tasks };
}

export function reducer(state: CtaState, action: CtaAction): CtaState {
  switch (action.type) {
    case 'typed':
      return { ...state, email: action.value, form: 'idle' };
    case 'submitted':
      return submitted(state);
    case 'sent':
      return sent(state);
    case 'reset':
      return { ...state, email: '', form: 'idle' };
    case 'replying':
      return withTask(state, action.index, 'replying');
    case 'resolved':
      return withTask(state, action.index, 'done');
  }
}

export function resolvedCountOf(state: CtaState) {
  const resolved = state.tasks.filter((status) => status === 'done');
  return resolved.length;
}

const TYPED_EMAIL = 'amina@lubumbashi-books.example';

const KEY_MS = 48;

export const SEND_MS = 1100;

function typing(text: string, startAfter: number): Step[] {
  const prefixes = prefixesOf(text);
  return prefixes.map((value, index) => ({
    after: keyDelayOf(index, startAfter, KEY_MS),
    by: 'demo',
    action: { type: 'typed', value },
  }));
}

function replying(after: number, index: number): Step {
  return { after, action: { type: 'replying', index } };
}

function resolved(after: number, index: number): Step {
  return { after, action: { type: 'resolved', index } };
}

/**
 * The queue clears on its own clock. Someone types an address and asks for the link while the
 * second conversation is being answered, and the rest of the queue goes on after the link is sent.
 */
export const SCRIPT: Step[] = [
  replying(1200, 0),
  resolved(1300, 0),
  replying(600, 1),
  ...typing(TYPED_EMAIL, 500),
  resolved(500, 1),
  {
    after: 900,
    by: 'demo',
    press: 'submit',
    action: { type: 'submitted' },
  },
  replying(1500, 2),
  resolved(1300, 2),
  replying(700, 3),
  resolved(1200, 3),
  replying(700, 4),
  resolved(1200, 4),
];

/** Under reduced motion the address is typed and the whole queue is cleared. */
export const RESTING: CtaState = {
  ...INITIAL,
  email: TYPED_EMAIL,
  tasks: allTasks('done'),
};

export const LOOP_AFTER_MS = 3600;

export type QueueTask = {
  id: string;
  title: string;
};

export const SECTION = {
  title: 'Start Monday with an empty queue',
  description:
    'Use your work email and Ferrywell sorts the conversations already waiting in your inbox. What it can answer lands in Done before you open the first one.',
  placeholder: 'you@company.com',
  emailLabel: 'Work email',
};

export const QUEUE = {
  title: 'Support queue',
  badge: 'Sample queue',
};

export const TASKS: QueueTask[] = [
  { id: 'refund', title: 'Refund for order 4821' },
  { id: 'password', title: 'Password reset for the Lubumbashi office' },
  { id: 'invoice', title: 'Invoice copy for March' },
  { id: 'delivery', title: 'Delivery to Goma is a day late' },
  { id: 'limits', title: 'Question about the API limits' },
];
